    function AutonomousMissionDetailHardened({mission,onClose,onChanged,notify}:{mission:any;onClose:()=>void;onChanged:(value:any)=>void;notify:(message:string,tone?:Toast['tone'])=>void}){const[busy,setBusy]=useState(false),[missionDiff,setMissionDiff]=useState<any>(null);const refresh=()=>api('/api/missions/'+mission.mission.id).then(onChanged);const start=async()=>{if(!window.confirm('O funcionário começará a executar as etapas do plano em sequência.\nO trabalho ficará isolado até você aplicar a missão.'))return;setBusy(true);try{await api('/api/missions/'+mission.mission.id+'/start',{method:'POST'});await refresh()}catch(e){notify(e instanceof Error?e.message:'Não foi possível iniciar a missão.','error')}finally{setBusy(false)}};const baseBranch=mission.mission.baseBranch||'BRANCH BASE';const alreadyApplied=mission.mission.environmentStatus==='applied';const viewDiff=async()=>{try{setMissionDiff(await api('/api/missions/'+mission.mission.id+'/diff'))}catch(e){notify(e instanceof Error?e.message:'Não foi possível carregar as alterações da missão.','error')}};const apply=async()=>{if(!alreadyApplied&&!window.confirm(`Aplicar todas as alterações desta missão na branch ${baseBranch}?\n\nNenhuma ação de push será executada. O worktree da missão será removido após sucesso. Em caso de conflito, o ambiente será preservado.`))return;setBusy(true);try{await api('/api/missions/'+mission.mission.id+'/apply',{method:'POST'});await refresh()}catch(e){notify(e instanceof Error?e.message:'Apply da missão bloqueado.','error')}finally{setBusy(false)}};const discard=async()=>{if(!window.confirm('Descartar a missão e remover seu ambiente isolado?'))return;setBusy(true);try{await api('/api/missions/'+mission.mission.id+'/discard',{method:'POST'});await refresh()}catch(e){notify(e instanceof Error?e.message:'Não foi possível descartar a missão.','error')}finally{setBusy(false)}};const status=mission.mission.status;const locked=busy||status==='planning'||status==='running';const selectCurrentMissionTask=(items:any[],missionStatus:string)=>{const order=missionStatus==='waiting_human'?['failed','blocked','running','approved']:['running','approved'];return order.map(value=>items.find((task:any)=>task.status===value)).find(Boolean)};const current=selectCurrentMissionTask(mission.tasks,status);const resume=async()=>{setBusy(true);try{const response=await api('/api/missions/'+mission.mission.id+'/resume',{method:'POST'});onChanged(response);await refresh()}catch(e){notify(e instanceof Error?e.message:'Não foi possível retomar a missão.','error')}finally{setBusy(false)}};const stageNames:any={planner:'Planner',developer:'Developer',tester:'Tester',reviewer:'Reviewer'};useEffect(()=>{if(!['running','waiting_human'].includes(mission.mission.status))return;const source=new EventSource('/events');const names=['mission.started','mission.task_started','mission.task_completed','mission.waiting_human','mission.completed','mission.failed','mission.resumed','mission.task_resumed'];const refreshFromEvent=(event:MessageEvent)=>{try{const envelope=JSON.parse(event.data||'{}');const data=envelope.data||envelope;if(data.missionId===mission.mission.id)void refresh()}catch{}};names.forEach(name=>source.addEventListener(name,refreshFromEvent));const timer=mission.mission.status==='running'?window.setInterval(()=>void refresh(),1000):undefined;return()=>{names.forEach(name=>source.removeEventListener(name,refreshFromEvent));if(timer)window.clearInterval(timer);source.close()}},[mission.mission.id,mission.mission.status]);return <Modal title={'MISSÃO · '+mission.mission.title} onClose={onClose} closable={!locked} closeOnBackdrop={!locked}><div className="mission-detail"><p className="eyebrow">FUNCIONÁRIO · {status==='approved'?'Pronto para trabalhar':status==='running'?'Trabalhando':status==='completed'?'Trabalho concluído':status==='waiting_human'?'Preciso de você':'Preparando trabalho'}</p><h3>{mission.mission.title}</h3><p>{mission.mission.request}</p><div className="mission-detail-grid"><div><strong>Branch base</strong><span className="mono">{baseBranch}</span></div><div><strong>Branch da missão</strong><span className="mono">{mission.mission.missionBranch||'—'}</span></div></div>{['running','waiting_human'].includes(status)&&current&&<div className="notice info"><strong>Etapa da missão: {String((mission.progress?.completed||0)+1).padStart(2,'0')} · {current.title}</strong><span>Pipeline: {stageNames[current.childTask?.currentStage||current.execution?.role]||current.childTask?.currentStage||'—'}</span>{current.execution&&<span>Provider: {providerLabel(current.execution.provider)} / {current.execution.model}</span>}{current.execution?.progressMessage&&<span>Mensagem: {current.execution.progressMessage}</span>}</div>}{status==='waiting_human'&&current&&<div className="notice warning"><strong>PRECISO DE VOCÊ</strong><span>Etapa: {String((mission.tasks.indexOf(current)+1)).padStart(2,'0')} · {current.title}</span>{current.execution&&<><span>Falhou em: {stageNames[current.execution.role]||current.execution.role}</span><span>Provider: {providerLabel(current.execution.provider)} / {current.execution.model}</span>{current.execution.error&&<span>Erro: {String(current.execution.error).slice(0,500)}</span>}</>}<span>Próxima tentativa: {stageNames[current.childTask?.currentStage||current.execution?.role]||current.childTask?.currentStage||'—'}</span><span>O pipeline foi interrompido e o ambiente foi preservado.</span></div>}<div className="mission-plan">{mission.tasks.map((task:any,index:number)=><article className="mission-plan-item" key={task.id}><strong>{task.status==='completed'?'✓':task.status==='running'?'→':'○'} {String(index+1).padStart(2,'0')} · {task.title}</strong><small>{task.status}</small></article>)}</div><div className="modal-foot">{status==='approved'&&<button className="primary" onClick={start} disabled={busy}>INICIAR MISSÃO</button>}{status==='waiting_human'&&<button className="primary" onClick={resume} disabled={busy}>{busy?'RETOMANDO...':'RETOMAR MISSÃO'}</button>}{status==='completed'&&alreadyApplied&&<div className="notice success"><strong>APLICADO NA {baseBranch}</strong>{mission.mission.environmentWarning&&<span>{mission.mission.environmentWarning}</span>}</div>}{status==='completed'&&!alreadyApplied&&<><button className="secondary" onClick={viewDiff} disabled={busy}>VER ALTERAÇÕES</button><button className="primary" onClick={apply} disabled={busy||missionDiff?.reviewComplete===false} title={missionDiff?.reviewComplete===false?'A revisão não contém todos os arquivos. Gere um diff completo antes de aplicar.':undefined}>APLICAR NA {baseBranch}</button></>}{status==='completed'&&alreadyApplied&&mission.mission.environmentWarning&&<button className="secondary" onClick={apply} disabled={busy}>TENTAR LIMPAR AMBIENTE</button>}{['running','waiting_human','completed','approved'].includes(status)&&!alreadyApplied&&<button className="secondary" onClick={discard} disabled={busy}>DESCARTAR MISSÃO</button>}</div></div>{missionDiff&&<Modal title="Alterações da missão" onClose={()=>setMissionDiff(null)}><p>{missionDiff.files?.length?`${missionDiff.files.length} arquivo(s) alterado(s).`:'Nenhuma alteração de arquivos detectada.'}</p>{missionDiff.files?.length&&<div className="diff-file-list">{missionDiff.files.map((file:any)=><div key={file.path}><b>{file.status}</b> {file.path}{file.binary&&<span> · Binário</span>}</div>)}</div>}{missionDiff.truncated&&<div className="notice warning">O diff foi truncado por tamanho.</div>}{missionDiff.reviewComplete===false&&<div className="notice warning"><strong>A revisão não contém todos os arquivos. Não aplique esta missão ainda.</strong>{missionDiff.omittedFiles?.length&&<span>Omitidos: {missionDiff.omittedFiles.join(', ')}</span>}</div>}<pre className="diff-viewer">{missionDiff.diff||'Nenhuma alteração de arquivos detectada.'}</pre></Modal>}</Modal>}
        function MissionPlanningFailedDetail({mission,onClose,onChanged,notify}:{mission:any;onClose:()=>void;onChanged:(value:any)=>void;notify:(message:string,tone?:Toast['tone'])=>void}){const[busy,setBusy]=useState(false);const retry=async()=>{setBusy(true);try{await api('/api/missions/'+mission.mission.id+'/plan',{method:'POST'})}catch(e){notify(e instanceof Error?e.message:'Não foi possível gerar o plano.','error')}finally{try{await api('/api/missions/'+mission.mission.id).then(onChanged)}catch(e){notify(e instanceof Error?e.message:'Não foi possível atualizar a missão.','error')}setBusy(false)}};return <Modal title={'MISSÃO · '+mission.mission.title} onClose={onClose} closable={!busy} closeOnBackdrop={!busy}><div className="mission-detail"><p className="eyebrow">FUNCIONÁRIO · Planejamento interrompido</p><h3>{mission.mission.title}</h3><p>Não foi possível gerar o plano.</p>{mission.mission.planningError&&<p className="refiner-error">Detalhes: {mission.mission.planningError}</p>}<p>Você pode tentar novamente.</p><div className="modal-foot"><button className="secondary" onClick={onClose} disabled={busy}>Cancelar</button><button className="primary" onClick={retry} disabled={busy}>{busy?'Gerando…':'TENTAR GERAR PLANO NOVAMENTE'}</button></div></div></Modal>}
        function MissionPlannerSummary({mission}:{mission:any}){const provider=mission?.mission?.missionPlannerProvider||mission?.mission?.plannerProvider||'mock';const model=mission?.mission?.missionPlannerModel||mission?.mission?.plannerModel||'mock-reasoning';const origin=mission?.mission?.missionPlannerOrigin||'default';const label=(value:string)=>value==='claude-code'?'Claude Code':value==='mock'?'Mock':value;const originLabel=(value:string)=>({workspace:'Workspace',global:'Global',environment:'Ambiente',default:'Padrão'} as any)[value]||value;return <section className="mission-planner-summary"><p className="eyebrow">PLANEJAMENTO</p><div><span>Provider</span><b>{label(provider)}</b></div><div><span>Modelo</span><b>{model}</b></div><div><span>Origem</span><b>{originLabel(origin)}</b></div></section>}
        function MissionDetailHost(props:any){const body=props.mission.mission.status==='failed'?<MissionPlanningFailedDetail {...props}/>:['draft','planning','plan_ready'].includes(props.mission.mission.status)?<MissionDetailEditorBeforeAutonomy {...props}/>:<AutonomousMissionDetailHardened {...props}/>;return <><MissionPlannerSummary mission={props.mission}/>{body}</>}
// @ts-ignore runtime replacement keeps the existing MissionSection wiring stable.
MissionDetailV2=MissionDetailHost;

const browserStatusLabel=(value:string)=>value==='PASSED'?'Aprovado':value==='FAILED'?'Falhou':value==='BLOCKED'?'TESTES INTERATIVOS · Bloqueado':value==='NOT_PLANNED'?'TESTES INTERATIVOS · Nenhum cenário interativo proposto':'Não executado';
function BrowserQaPanel({task}:{task:Task}){const execution=[...(task.executions||[])].reverse().find((item:any)=>item.role==='tester'&&item.structuredResult?.browserQa);const qa=execution?.structuredResult?.browserQa;const coverage=execution?.structuredResult?.acceptanceCoverage;return <section className="panel browser-qa-panel"><div className="panel-title"><span>QA NO NAVEGADOR</span><span className="muted">{browserStatusLabel(qa?.status||'')}</span></div>{!qa?<p className="muted">Nenhuma execução de QA no navegador foi registrada.</p>:<><p>{qa.summary||'Smoke QA concluído.'}</p><div className="acceptance-coverage">{coverage&&<><small>COBERTURA DOS CRITÉRIOS</small><p>{coverage.covered}/{coverage.total} verificados</p>{(coverage.criteria||[]).map((item:any)=><div className="posture-row" key={item.criterionId}><span>{item.criterionId} · {item.criterionText}</span><b>{item.status==='PASSED'?'Verificado':item.status==='FAILED'?'Falhou':'Sem cobertura'}</b><small>{item.message}{item.evidence?.scenario&&` · cenário ${item.evidence.scenario}`}{item.evidence?.step!==undefined&&` · passo ${item.evidence.step}`}{item.evidence?.action&&` · ${item.evidence.action}`}{item.evidence?.targetSummary&&` · ${item.evidence.targetSummary}`}{item.evidence?.expectedSummary&&` · ${item.evidence.expectedSummary}`}</small>{item.evidence?.screenshotFilename&&<a href={`/api/tasks/${task.id}/browser-qa/screenshots/${encodeURIComponent(item.evidence.screenshotFilename)}`} target="_blank" rel="noreferrer">Ver evidência</a>}</div>)}</>}</div>{qa.interactiveStatus==='FAILED'&&qa.interactivePlanError&&<div className="browser-qa-scenarios"><small>TESTES INTERATIVOS</small><p>Falhou</p><small>Plano inválido: {qa.interactivePlanError.message}</small></div>}{qa.interactiveStatus==='NOT_PLANNED'&&<div className="browser-qa-scenarios"><small>TESTES INTERATIVOS</small><p>Nenhum cenário interativo proposto.</p></div>}<div className="posture-row"><span>Runtime</span><b>{execution?.structuredResult?.runtime?.type||'—'}</b></div><div className="posture-row"><span>URL</span><b className="mono">{execution?.structuredResult?.runtime?.baseUrl||qa.baseUrl||'—'}</b></div>{qa.externalOrigins?.length>0&&<div className="browser-qa-external"><small>Recursos externos</small>{qa.externalOrigins.map((origin:string)=><span key={origin} className="mono">{origin}</span>)}</div>}<div className="browser-qa-routes">{(qa.routes||[]).map((route:any)=><div className="posture-row" key={route.route}><span>{route.status==='PASSED'?'✓':'✕'} {route.route}</span><b>{route.httpStatus?`HTTP ${route.httpStatus}`: '—'}</b>{route.errors?.length>0&&<small>{route.errors.map((error:any)=>typeof error==='string'?error:`${error.type}: ${error.message}`).join(' · ')}</small>}{route.screenshot?.filename&&<a href={`/api/tasks/${task.id}/browser-qa/screenshots/${encodeURIComponent(route.screenshot.filename)}`} target="_blank" rel="noreferrer">Screenshot</a>}</div>)}</div>{qa.scenarios?.length>0&&<div className="browser-qa-scenarios"><small>TESTES INTERATIVOS</small>{qa.scenarios.map((scenario:any)=><div className="browser-qa-scenario" key={scenario.name}><strong>{scenario.status==='PASSED'?'✓':'✕'} {scenario.name}</strong>{scenario.steps?.map((step:any)=><span key={step.index}> {step.status==='PASSED'?'✓':'✕'} {describeBrowserStep(step)}</span>)}{scenario.error&&<small>{scenario.error}</small>}{scenario.screenshots?.map((shot:string)=><a key={shot} href={`/api/tasks/${task.id}/browser-qa/screenshots/${encodeURIComponent(shot.split(/[\\\\/]/).pop()||shot)}`} target="_blank" rel="noreferrer">Screenshot</a>)}</div>)}</div>}</>}</section>}
